import{_ as t,o as e,c as u,a2 as a}from"./chunks/framework.Crpw6aS5.js";const s=JSON.parse('{"title":"1969年 · 主动鸣金收兵","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1969年.md","filePath":"05_quotes/by-year/1969年.md"}'),q={name:"05_quotes/by-year/1969年.md"};function l(c,o,r,p,b,_){return e(),u("div",null,[...o[0]||(o[0]=[a('<h1 id="_1969年-·-主动鸣金收兵" tabindex="-1">1969年 · 主动鸣金收兵 <a class="header-anchor" href="#_1969年-·-主动鸣金收兵" aria-label="Permalink to &quot;1969年 · 主动鸣金收兵&quot;">​</a></h1><blockquote><p>&quot;我不想一辈子都忙着追赶投资&#39;兔子&#39;，唯一的减速方式就是停下。&quot;——巴菲特（38岁）</p></blockquote><p>本页收录1969年致股东信中的经典语录。巴菲特在这一年正式宣布解散合伙公司，原因不是业绩差，而是机会枯竭。在市场最疯狂、他却找不到方向时，选择急流勇退——这是投资生涯中最艰难也最理性的决定。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>&quot;我不想一辈子都忙着追赶投资&#39;兔子&#39;，唯一的减速方式就是停下。&quot;</p></blockquote><blockquote><p>&quot;过去20年里，依赖量化分析的投资机会持续枯竭，如今几乎消失殆尽。&quot;</p></blockquote><blockquote><p>&quot;只要公开参与投资，我就难免好胜。我不想一辈子都忙着追赶投资&#39;兔子&#39;。&quot;</p></blockquote><blockquote><p>&quot;坦白说，即便有顶级投资思路，我仍会在1970年甚至1971年继续运营合伙公司。我并非想继续，只是更想以好成绩收尾。但我看不到任何能带来优质业绩的机会，也不愿拿着别人的钱碰运气。&quot;</p></blockquote><blockquote><p>&quot;记录错误令人不快，选择性披露更让我反感。今年的糟糕表现完全是我的责任，并非运气不佳，而是对政府政策快速变化判断失误。&quot;</p></blockquote><blockquote><p>&quot;我非常认可控股公司的管理层，希望与他们建立长期合作。我绝不为高价出售经营良好、由我敬重之人管理的企业，除非特殊情况。&quot;</p></blockquote><blockquote><p>&quot;最重要的，是为不愿自行打理资产的合伙人推荐替代资金管理人。我不会只说一句&#39;祝好运&#39;就把资金交出去，我会推荐一位我亲自为家人及需终身负责的亲友委托资金的管理人。&quot;</p></blockquote><blockquote><p>&quot;我知道60岁的人生目标，应与20岁不同。若不脱离耗费我成年后18年全部精力的投资事业，我无法开启适配未来的新人生。&quot;</p></blockquote><blockquote><p>&quot;我不适应当下的市场环境，不想为了英雄式收官，毁掉过往良好记录。&quot;</p></blockquote><blockquote><p>&quot;1956年，我估计纽约证券交易所每三天的成交量就相当于1956年全年。也许那些1956年觉得自己在疯狂年代入局的人，现在会觉得现在的疯狂程度远不止于此。&quot;</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1969年是巴菲特合伙公司的终点。他在这一年正式向所有有限合伙人发出退休通知，计划在年底前完成清算。直接原因是投资机会枯竭：1亿美元规模，几乎找不到低于300万美元且有吸引力的标的；深层原因是个人状态——&quot;只要公开承诺了目标，我就全力以赴，这越来越没必要&quot;。他向每位合伙人提供了三种退出选择，并亲自推荐了接班人。</p>',18)])])}const n=t(q,[["render",l]]);export{s as __pageData,n as default};
